{
  "name": "@renjfk/opencode-notify",
  "version": "1.1.0",
  "description": "Attention notifications for OpenCode. Blinks Zellij tab, plays a sound, and posts a macOS desktop notification when a session goes idle, requests permission, or asks a question.",
  "keywords": [
    "ghostty",
    "macos",
    "notification",
    "notify",
    "opencode",
    "plugin",
    "terminal-notifier",
    "zellij"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/renjfk/opencode-notify.git"
  },
  "files": [
    "index.js",
    "lib"
  ],
  "type": "module",
  "main": "index.js",
  "exports": {
    "./tui": {
      "import": "./index.js"
    }
  },
  "scripts": {
    "test": "node --test",
    "lint": "npx oxlint .",
    "fmt": "npx oxfmt --check .",
    "fmt:fix": "npx oxfmt --write .",
    "check": "npm run test && npm run lint && npm run fmt",
    "e2e": "./e2e/run.sh",
    "e2e:docker": "docker build -f e2e/Dockerfile -t opencode-notify-e2e . && docker run --rm -e E2E_ENDPOINT -e E2E_MODEL -e E2E_API_KEY_ENV -e E2E_PROVIDER_PACKAGE -e \"${E2E_API_KEY_ENV:-E2E_API_KEY}\" opencode-notify-e2e",
    "prepack": "npm run check"
  },
  "devDependencies": {
    "oxfmt": "0.65.0",
    "oxlint": "1.80.0"
  }
}
